import{_ as t,c as a,o as s,a2 as r}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"acceptsPortalShield","description":"Returns whether portals may be shielded on a network.","frontmatter":{"title":"acceptsPortalShield","description":"Returns whether portals may be shielded on a network.","rawMarkdown":"---\\ntitle: acceptsPortalShield\\ndescription: Returns whether portals may be shielded on a network.\\n---\\n\\n# acceptsPortalShield\\n\\nReturns whether portal deposits may be shielded on a network.\\n\\nCarrying an `aggregatorContractAddress` is not enough. A direct-shield-only deployment\\n(such as Gnosis) has no portal factory, so every portal shield there reverts. Network\\nmetadata flags such a network with `portalShieldEnabled: false`, and the backend applies\\nthe same predicate. Anything that models the deposit pipeline — the shielding target, the\\nentry bridge, fee estimates — should use this rather than the bare address.\\n\\nDirect shielding from a wallet the user controls is unaffected.\\n\\n## Import\\n\\n```ts\\nimport { acceptsPortalShield } from \\"@0xcurvy/curvy-sdk/config\\";\\n```\\n\\n## Usage\\n\\nShield on the source chain when it accepts portal deposits, and fall back to the default\\naggregator network otherwise:\\n\\n```ts\\nconst shielding = acceptsPortalShield(fromNetwork) ? fromNetwork : getDefaultAggregatorNetwork();\\n```\\n\\n## Returns\\n\\n`boolean`\\n\\n`true` when the network has an aggregator and does not opt out of portal shielding.\\nMetadata that predates `portalShieldEnabled` is treated as portal-capable.\\n\\n## Parameters\\n\\n### `network`\\n\\n- **Type:** `Network`\\n\\nThe network to check.\\n\\n## Related\\n\\n- [`getDefaultAggregatorNetwork`](/sdk/config/getDefaultAggregatorNetwork)\\n- [`getActiveNetworks`](/sdk/config/getActiveNetworks)\\n","rawMarkdownPath":"/_raw/sdk/config/acceptsPortalShield.md","rawMarkdownTitle":"acceptsPortalShield","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/config/acceptsPortalShield.md"},"headers":[],"relativePath":"sdk/config/acceptsPortalShield.md","filePath":"sdk/config/acceptsPortalShield.md","lastUpdated":1790004279000}'),o={name:"sdk/config/acceptsPortalShield.md"};function i(n,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="acceptsportalshield" tabindex="-1">acceptsPortalShield <a class="header-anchor" href="#acceptsportalshield" aria-label="Permalink to &quot;acceptsPortalShield&quot;">​</a></h1><p>Returns whether portal deposits may be shielded on a network.</p><p>Carrying an <code>aggregatorContractAddress</code> is not enough. A direct-shield-only deployment (such as Gnosis) has no portal factory, so every portal shield there reverts. Network metadata flags such a network with <code>portalShieldEnabled: false</code>, and the backend applies the same predicate. Anything that models the deposit pipeline — the shielding target, the entry bridge, fee estimates — should use this rather than the bare address.</p><p>Direct shielding from a wallet the user controls is unaffected.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { acceptsPortalShield } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@0xcurvy/curvy-sdk/config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>Shield on the source chain when it accepts portal deposits, and fall back to the default aggregator network otherwise:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> shielding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> acceptsPortalShield</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fromNetwork) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fromNetwork </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getDefaultAggregatorNetwork</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h2><p><code>boolean</code></p><p><code>true</code> when the network has an aggregator and does not opt out of portal shielding. Metadata that predates <code>portalShieldEnabled</code> is treated as portal-capable.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><h3 id="network" tabindex="-1"><code>network</code> <a class="header-anchor" href="#network" aria-label="Permalink to &quot;`network`&quot;">​</a></h3><ul><li><strong>Type:</strong> <code>Network</code></li></ul><p>The network to check.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/sdk/config/getDefaultAggregatorNetwork.html"><code>getDefaultAggregatorNetwork</code></a></li><li><a href="/sdk/config/getActiveNetworks.html"><code>getActiveNetworks</code></a></li></ul>',18)])])}const g=t(o,[["render",i]]);export{k as __pageData,g as default};
